def transform(grid):
    out=[row[:] for row in grid]
    marks=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    if len(marks)<2: return out
    # The colored pattern adjacent to the lower marker is the source; copy its offsets to the upper marker.
    src=max(marks, key=lambda p:p[0])
    dst=min(marks, key=lambda p:p[0])
    pattern=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v and (r,c)!=src and (r,c)!=dst:
                # source motif sits below the lower marker
                if r>src[0]: pattern.append((r-src[0],c-src[1],v))
    for dr,dc,v in pattern:
        rr,cc=dst[0]+dr,dst[1]+dc
        if 0<=rr<len(out) and 0<=cc<len(out[0]): out[rr][cc]=v
    out[dst[0]][dst[1]]=0
    return out
